<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useFitness, tone } from './store'
import { clone, newDay, formatRest, addDays, cycleDays, cycleOn, setCount, type TrainingDay, type TrainingTemplate } from '../../../shared/fitness'
import { localDate } from '../../../shared/date'
import ItemEditor from './ItemEditor.vue'
import DesignArt from './DesignArt.vue'
import ExerciseImage from './ExerciseImage.vue'
import { confirmDelete } from '../lib/api'
const props=defineProps<{page:string}>(),emit=defineEmits<{navigate:[page:string]}>(),fs=useFitness(),today=localDate()
const cycle=ref(Math.max(0,cycleOn(fs.data,today))),selected=ref(Math.max(0,Math.floor((Date.parse(today)-Date.parse(fs.data.startDate))/86400000))%Math.max(1,fs.data.rhythm.length)),editing=ref(false),scope=ref('one'),draft=ref<TrainingDay>(newDay()),templateId=ref(fs.data.templates[0]?.id||''),search=ref(''),templateDraft=ref<TrainingTemplate>(),step=ref(1),trainDays=ref(3),restDays=ref(1),pending=ref<TrainingDay[]>([]),startDate=ref(fs.data.startDate)
const days=computed(()=>cycleDays(fs.data,cycle.value)),focused=computed(()=>days.value[selected.value]||days.value[0]),trainCount=computed(()=>fs.data.rhythm.filter(d=>d.type!=='休息').length),restCount=computed(()=>fs.data.rhythm.length-trainCount.value),templates=computed(()=>fs.data.templates.filter(t=>t.title.includes(search.value)))
const dateOf=(i:number,c=cycle.value)=>addDays(fs.data.startDate,c*fs.data.rhythm.length+i),short=(d:string)=>d.slice(5).replace('-','.'),range=(c:number)=>short(dateOf(0,c))+' — '+short(dateOf(fs.data.rhythm.length-1,c)),art=(d:TrainingDay)=>d.type==='休息'?'peach':d.type==='腿'?'pink':tone(d.type)
watch(()=>props.page,p=>{editing.value=false;if(p!=='templates')templateDraft.value=undefined;step.value=1;trainDays.value=trainCount.value||3;restDays.value=fs.data.rhythm.length?restCount.value:1;startDate.value=fs.data.startDate||today},{immediate:true})
watch(cycle,()=>selected.value=Math.min(selected.value,days.value.length-1))
function editDay(){draft.value=clone(focused.value);scope.value='one';editing.value=true}
function chooseTemplate(){const t=fs.data.templates.find(t=>t.id===draft.value.templateId);if(t)draft.value={...clone(t),templateId:t.id}}
async function apply(){if(draft.value.type==='休息')draft.value.items=[];if(scope.value==='future'){for(let c=0;c<cycle.value;c++)if(!fs.data.overrides[c])fs.data.overrides[c]=clone(fs.data.rhythm);fs.data.rhythm[selected.value]=clone(draft.value);for(const [c,ds] of Object.entries(fs.data.overrides))if(+c>=cycle.value)ds[selected.value]=clone(draft.value)}else{fs.data.overrides[cycle.value]=clone(days.value);fs.data.overrides[cycle.value][selected.value]=clone(draft.value)}if(await fs.save('训练日已保存'))editing.value=false}
function openTemplate(t:TrainingTemplate){templateDraft.value=clone(t);templateId.value=t.id}
function addTemplate(){templateDraft.value={...newDay('新训练内容'),id:crypto.randomUUID()};emit('navigate','templates')}
async function saveTemplate(){const t=templateDraft.value!;const index=fs.data.templates.findIndex(x=>x.id===t.id);if(index<0)fs.data.templates.push(clone(t));else fs.data.templates[index]=clone(t);if(await fs.save('常用训练内容已保存'))templateDraft.value=undefined}
async function deleteTemplate(t:TrainingTemplate){if(await confirmDelete(t.title)){fs.data.templates=fs.data.templates.filter(x=>x.id!==t.id);await fs.save();templateDraft.value=undefined}}
function nextStep(){if(step.value===1){pending.value=Array.from({length:trainDays.value+restDays.value},(_,i)=>i<trainDays.value?clone(fs.data.rhythm.filter(d=>d.type!=='休息')[i]||fs.data.templates[i%Math.max(1,fs.data.templates.length)]||newDay()):newDay('休息与恢复','休息'))}step.value++}
function assign(i:number,id:string){const t=fs.data.templates.find(t=>t.id===id);pending.value[i]=t?{...clone(t),templateId:t.id}:id==='rest'?newDay('休息与恢复','休息'):newDay()}
async function saveRhythm(){fs.data.rhythm=clone(pending.value);fs.data.startDate=startDate.value;fs.data.overrides={};if(await fs.save('循环已保存，历史记录保持原样')){cycle.value=0;selected.value=0;emit('navigate','overview')}}
defineExpose({addTemplate})
</script>
<template><div class="embedded-plan">
<template v-if="page==='overview'&&!editing">
<section class="fit-card embedded-banner"><div><small>我的循环节奏</small><h2>练{{ trainCount }}休{{ restCount }}</h2><p>每 {{ fs.data.rhythm.length }} 天一轮 · 按自己的节奏重复。</p></div><span>{{ short(fs.data.startDate) }} 开始 · 可随时调整</span><DesignArt kind="hero"/></section>
<div class="embedded-plan-layout"><div class="fit-main-column"><section class="fit-card embedded-cycle"><header><div><h2>本轮安排</h2><p class="fit-muted">选择一天，查看或调整训练内容。</p></div><div class="fit-cycle-nav"><button aria-label="上一轮" :disabled="cycle===0" @click="cycle--">‹</button><span>第 {{ cycle+1 }} 轮 · {{ range(cycle) }}</span><button aria-label="下一轮" @click="cycle++">›</button></div></header><div class="embedded-day-grid" :style="{'--count':Math.min(days.length,4)}"><button v-for="(d,i) in days" :key="i" class="embedded-day" :class="[tone(d.type),{selected:selected===i}]" :aria-pressed="selected===i" @click="selected=i"><span class="embedded-date"><b>{{ short(dateOf(i)) }}</b><small>{{ dateOf(i)===today?'今天':'第 '+(i+1)+' 天' }}</small></span><h3>{{ d.title }}</h3><small>{{ d.type==='休息'?'给身体一点恢复时间':d.items.length+' 个动作 · '+setCount(d.items)+' 组' }}</small><DesignArt :kind="art(d)"/><span class="embedded-day-foot">{{ fs.data.overrides[cycle]?'已单独调整':d.type==='休息'?'恢复日':'沿用常用训练内容' }} <b>›</b></span></button></div><p class="embedded-cycle-foot">⟳ 下一轮自动延续常规安排，个别日期可以单独调整。<span>{{ fs.data.overrides[cycle]?'本轮有单独调整':'本轮按常规安排' }}</span></p></section>
<section class="fit-card embedded-day-focus"><header><div><small class="fit-muted">{{ dateOf(selected).replaceAll('-','.') }} · 第 {{ selected+1 }} 天</small><h2>{{ focused.title }}</h2><p class="fit-muted">{{ focused.items.length }} 个计划动作 · {{ setCount(focused.items) }} 组</p></div><button class="fit-button" @click="editDay">✎ 调整这一天</button></header><div class="embedded-table-wrap"><table class="fit-table"><thead><tr><th>动作</th><th>目标组次</th><th>参考重量</th><th>组间休息</th></tr></thead><tbody><tr v-for="item in focused.items" :key="item.exerciseId"><td><span class="fit-mini-action"><ExerciseImage :image="fs.exercise(item.exerciseId)?.image" :alt="fs.exercise(item.exerciseId)?.name"/><b>{{ fs.exercise(item.exerciseId)?.name||'已删除动作' }}</b></span></td><td>{{ item.sets.length }} × {{ fs.exercise(item.exerciseId)?.measure==='time'?(item.sets[0]?.duration??'—')+' 秒':fs.exercise(item.exerciseId)?.measure==='distance'?(item.sets[0]?.distance??'—')+' 米':(item.sets[0]?.reps??'—')+' 次' }}</td><td>{{ fs.exercise(item.exerciseId)?.measure==='weight'?(item.sets[0]?.weight??'—')+' kg':'—' }}</td><td>{{ formatRest(item) }}</td></tr></tbody></table></div><div v-if="!focused.items.length" class="embedded-rest"><DesignArt :kind="focused.type==='休息'?'peach':'mint'"/><h3>{{ focused.type==='休息'?'给身体留一点恢复时间。':'这一天还没有安排动作。' }}</h3></div><p v-if="focused.notes" class="fit-note">{{ focused.notes }}</p><p class="fit-muted">ⓘ 这是计划目标，不代表实际完成；练过之后，到“训练记录”补录。</p></section></div>
<aside class="fit-side-column"><section class="fit-card"><header><h2>常用训练内容</h2><button class="fit-text" @click="emit('navigate','templates')">管理 ›</button></header><button v-for="t in fs.data.templates" :key="t.id" class="embedded-training-tile" @click="openTemplate(t);emit('navigate','templates')"><DesignArt :kind="art(t)"/><span><b>{{ t.title }}</b><small>{{ t.items.length }} 个动作 · {{ setCount(t.items) }} 组</small></span><span>›</span></button><p class="fit-muted">保存常练的动作组合，在计划里按天选用。</p></section><section class="fit-card"><h3>✎ 这一轮的调整</h3><p class="fit-muted">{{ fs.data.overrides[cycle]?'本轮有单独调整。点选日期查看内容。':'本轮还没有单独调整。临时换内容或休息，只需修改对应日期。' }}</p></section></aside></div></template>
<template v-if="page==='overview'&&editing"><button class="fit-text" @click="editing=false">‹ 返回本轮安排</button><section class="fit-card embedded-editor"><header><div><h2>调整这一天</h2><p class="fit-muted">{{ dateOf(selected) }} · 不会修改过去的训练记录</p></div></header><div class="fit-radio-pair"><label><input type="radio" :checked="draft.type!=='休息'" @change="draft.type='自定义'"/>训练日</label><label><input type="radio" :checked="draft.type==='休息'" @change="draft=newDay('休息与恢复','休息')"/>休息日</label></div><div class="fit-form-grid"><label>训练名称<input v-model="draft.title"/></label><label v-if="draft.type!=='休息'">选择常用训练内容<select v-model="draft.templateId" @change="chooseTemplate"><option value="">单独编排</option><option v-for="t in fs.data.templates" :value="t.id">{{ t.title }}</option></select></label></div><ItemEditor v-if="draft.type!=='休息'" :items="draft.items"/><label class="fit-label">这一天的备注<textarea v-model="draft.notes"/></label><div class="embedded-save-row"><label><input type="radio" v-model="scope" value="one"/>仅修改这一天</label><label><input type="radio" v-model="scope" value="future"/>今后每轮的这一天</label><button class="fit-primary" @click="apply">保存调整</button></div></section></template>
<template v-if="page==='cycles'"><section class="fit-card embedded-wizard"><div class="embedded-stepper"><span v-for="(name,i) in ['设置节奏','安排内容','确认循环']" :class="{active:step===i+1}"><b>{{ i+1 }}</b>{{ name }}</span></div><template v-if="step===1"><h2>你习惯怎样安排训练？</h2><p class="fit-muted">按训练天数和休息天数循环，不必跟着星期走。</p><div class="embedded-presets"><button v-for="n in [2,3,4,5]" class="fit-button" :class="{chosen:trainDays===n&&restDays===1}" @click="trainDays=n;restDays=1">练{{ n }}休1</button></div><div class="fit-form-grid"><label>连续训练天数<input type="number" v-model.number="trainDays" min="1" max="14"/></label><label>连续休息天数<input type="number" v-model.number="restDays" min="0" max="7"/></label></div></template><template v-if="step===2"><h2>为每一天选好常用训练内容</h2><p class="fit-muted">这里只设置默认安排。临时变动，回到计划点选日期即可。</p><label v-for="(d,i) in pending" class="embedded-rhythm-row"><b>第 {{ i+1 }} 天</b><select :value="d.type==='休息'?'rest':d.templateId||''" @change="assign(i,($event.target as HTMLSelectElement).value)"><option value="">自定义训练（稍后编排）</option><option v-for="t in fs.data.templates" :value="t.id">{{ t.title }}</option><option value="rest">休息与恢复</option></select></label></template><template v-if="step===3"><h2>按自己的节奏，循环下去。</h2><p class="fit-muted">每 {{ pending.length }} 天一轮，单独日期随时可以调整。</p><label class="fit-label">开始日期<input type="date" v-model="startDate" required/></label><div class="embedded-presets"><span v-for="d in pending" class="fit-badge" :class="tone(d.type)">{{ d.title }}</span></div><p class="fit-note">保存新的循环会重新生成未来安排，清除现有的单日调整；历史训练记录保持不变。</p></template><div class="embedded-save-row"><button v-if="step>1" class="fit-button" @click="step--">上一步</button><button v-if="step<3" class="fit-primary" :disabled="!Number.isInteger(trainDays)||trainDays<1||trainDays>14||!Number.isInteger(restDays)||restDays<0||restDays>7" @click="nextStep">下一步 →</button><button v-else class="fit-primary" :disabled="!startDate" @click="saveRhythm">保存循环</button></div></section></template>
<template v-if="page==='templates'"><template v-if="!templateDraft"><div class="embedded-search"><input v-model="search" placeholder="搜索常用训练内容"/></div><div class="embedded-workout-grid"><section v-for="t in templates" :key="t.id" class="fit-card embedded-workout-card"><DesignArt :kind="art(t)"/><h2>{{ t.title }}</h2><p class="fit-muted">{{ t.items.length }} 个动作 · {{ setCount(t.items) }} 组</p><p v-for="i in t.items.slice(0,4)" class="fit-muted">{{ fs.exercise(i.exerciseId)?.name||'已删除动作' }}</p><footer><small>在计划中按天选用</small><button class="fit-button" @click="openTemplate(t)">编辑内容</button></footer></section></div><p v-if="!templates.length" class="fit-empty">还没有常用训练内容，点击“新建训练内容”开始。</p></template><section v-else class="fit-card embedded-editor"><button class="fit-text" @click="templateDraft=undefined">‹ 返回常用训练内容</button><div class="fit-form-grid"><label>训练名称<input v-model="templateDraft.title"/></label><label>训练分类<select v-model="templateDraft.type"><option v-for="t in ['推','拉','腿','有氧','自定义']">{{ t }}</option></select></label></div><ItemEditor :items="templateDraft.items"/><label class="fit-label">训练备注<textarea v-model="templateDraft.notes"/></label><div class="embedded-save-row"><button class="fit-text" @click="deleteTemplate(templateDraft)">删除这份内容</button><small>保存后可在计划中选用，不会自动改写已有安排。</small><button class="fit-primary" :disabled="!templateDraft.title.trim()" @click="saveTemplate">保存训练内容</button></div></section></template>
</div></template>
